function hostIn(url, domains) {
  let host;
  try {
    host = new URL(url).hostname.toLowerCase().replace(/^www\./, "");
  } catch {
    return false;
  }
  const path = (() => {
    try {
      return new URL(url).pathname.toLowerCase();
    } catch {
      return "";
    }
  })();
  return domains.some((d) => {
    return host === d || host.endsWith(`.${d}`) || d.includes("/") && `${host}${path}`.startsWith(d);
  });
}
