    targetPersonId: str3(c.payload.targetPersonId) ?? "",
    targetName: str3(c.payload.targetName) ?? "them",
    company: str3(c.payload.company),
    note: str3(c.payload.note) ?? "",
    goalId: str3(c.payload.goalId)
