// supabase/functions/_shared/research/dossier.ts
var DOSSIER_REUSE_MS = 30 * 864e5;
var EXA_CACHE_MS = 7 * 864e5;
var SYNTH_OUT_USD = 2e3 * 2e-5;

// supabase/functions/_shared/research/run.ts
async function dossierRow(db2, userId, personId) {
  const [r] = await db2.sql`
    select * from orbit.dossiers where user_id = ${userId}::uuid and person_id = ${personId}::uuid`;
  return r;
}
var toDossier = (r) => dossierFromRow({ ...isoRow(r), cost_usd: String(r.cost_usd ?? "0") });
async function ownedPerson(db2, userId, personId) {
  if (typeof personId !== "string" || !/^[0-9a-f-]{36}$/i.test(personId))
    throw new HttpError(400, "bad_request", "personId is required");
  const [p] = await db2.sql`
    select id from orbit.people where id = ${personId}::uuid and user_id = ${userId}::uuid and deleted_at is null`;
  if (!p) throw new HttpError(404, "not_found", "no such person");
  return p.id;
}
async function queueDossier(s, userId, personId, payload, key) {
  await s.queue.enqueue({
    kind: "enrich.dossier",
    userId,
    payload: { personId, ...payload },
    dedupeKey: key
  });
}
async function requestDossier(s, userId, req) {
  const personId = await ownedPerson(s.db, userId, req.personId);
  const goalId = typeof req.goalId === "string" ? req.goalId : null;
  const refresh2 = req.refresh === true;
  const now = s.now();
  const row = await dossierRow(s.db, userId, personId);
  if (row && !refresh2) {
    const status3 = row.status;
    const fresh = new Date(row.expires_at).getTime() > now.getTime();
    if ((status3 === "ready" || status3 === "partial") && row.content && fresh)
      return { status: status3, dossier: toDossier(row) };
    if (status3 === "needs_disambiguation") return { status: status3, dossier: toDossier(row) };
    if (status3 === "pending" && now.getTime() - new Date(row.updated_at).getTime() < 10 * 6e4)
      return { status: "queued", dossier: toDossier(row) };
  }
  await s.db.sql`
    insert into orbit.dossiers (user_id, person_id, goal_id, status, expires_at)
    values (${userId}::uuid, ${personId}::uuid, ${goalId}::uuid, 'pending', ${new Date(now.getTime() + 864e5)}::timestamptz)
    on conflict (user_id, person_id) do update set status = 'pending', goal_id = coalesce(excluded.goal_id, orbit.dossiers.goal_id),
      error = null`;
  const key = refresh2 ? `dossier:${personId}:refresh:${now.toISOString().slice(0, 16)}` : `dossier:${personId}`;
  await queueDossier(s, userId, personId, { goalId, refresh: refresh2 }, key);
  const after = await dossierRow(s.db, userId, personId);
  return { status: "queued", dossier: after ? toDossier(after) : null };
}
async function getDossier(db2, userId, personId) {
  const id = await ownedPerson(db2, userId, personId);
  const row = await dossierRow(db2, userId, id);
  return row ? toDossier(row) : null;
}
async function chooseCandidate(s, userId, req) {
  const personId = await ownedPerson(s.db, userId, req.personId);
  const row = await dossierRow(s.db, userId, personId);
  if (row?.status !== "needs_disambiguation")
    throw new HttpError(409, "not_ambiguous", "there is no choice to make for this person");
  const cands = row.candidates ?? [];
  const i = Number(req.candidateIndex);
  if (!Number.isInteger(i) || i < 0 || i >= cands.length)
    throw new HttpError(400, "bad_request", "no such candidate");
  const c = cands[i];
  const url = cleanLinkedInUrl(c.url);
  await s.db.sql`
    update orbit.people set org_raw = coalesce(${c.org ?? null}, org_raw),
           linkedin_url = coalesce(${url ?? null}, linkedin_url), linkedin_slug = coalesce(${linkedInSlugOf(url) ?? null}, linkedin_slug)
     where id = ${personId}::uuid and user_id = ${userId}::uuid`;
  await s.db.sql`
    update orbit.dossiers set status = 'pending', error = null
     where user_id = ${userId}::uuid and person_id = ${personId}::uuid`;
  await queueDossier(
    s,
    userId,
    personId,
    { refresh: true, chosen: c },
    `dossier:${personId}:choose:${s.now().toISOString().slice(0, 16)}`
  );
  const after = await dossierRow(s.db, userId, personId);
  return { status: "queued", dossier: after ? toDossier(after) : null };
}

// supabase/functions/orbit-api/routes/research.ts
async function person(ctx) {
  const r = await requestDossier(ctx.services(), ctx.userId, await body(ctx));
  return json(r.status === "queued" ? 202 : 200, r);
}
async function get(ctx) {
  const b = await body(ctx);
  return json(200, { dossier: await getDossier(ctx.db, ctx.userId, b.personId) });
}
async function choose(ctx) {
  return json(202, await chooseCandidate(ctx.services(), ctx.userId, await body(ctx)));
}
var researchRoutes = {
  "/research/person": { method: "POST", auth: true, run: person },
  "/research/get": { method: "POST", auth: true, run: get },
  "/research/choose": { method: "POST", auth: true, run: choose }
};

// supabase/functions/orbit-api/routes/scores.ts
async function scoreRow(ctx, personId) {
  const [r] = await ctx.db.sql`
    select ts.score, ts.band, ts.features, ts.contributions, ts.explanation, ts.model_version, ts.computed_at,
           tl.closeness
      from orbit.tie_scores ts
      left join orbit.tie_labels tl on tl.user_id = ts.user_id and tl.person_id = ts.person_id
     where ts.user_id = ${ctx.userId}::uuid and ts.person_id = ${personId}::uuid`;
  return r;
}
function explainOf(personId, r) {
  const contributions = {};
  for (const [k, v] of Object.entries(r.contributions ?? {})) contributions[k] = num(v);
  return {
    personId,
    score: num(r.score),
    band: r.band,
    explanation: r.explanation ?? [],
    contributions,
    modelVersion: r.model_version,
    computedAt: iso(r.computed_at),
    ...r.closeness ? { labelled: r.closeness } : {}
  };
}
async function ownPerson(ctx, personId) {
  const [p] = await ctx.db.sql`
    select 1 from orbit.people where id = ${personId}::uuid and user_id = ${ctx.userId}::uuid and deleted_at is null`;
  if (!p) throw new HttpError(404, "not_found", "no such person");
}
async function explain(ctx) {
  const personId = uuid(await body(ctx), "personId");
  await ownPerson(ctx, personId);
  const [r] = await Promise.all([scoreRow(ctx, personId), requestReads(ctx.db, ctx.userId, [personId])]);
  if (!r) throw new HttpError(404, "not_scored", "this person has no score yet");
  return json(200, explainOf(personId, r));
}
async function label(ctx) {
  const b = await body(ctx);
  const personId = uuid(b, "personId");
  const closeness = Number(b.closeness);
  if (![1, 2, 3, 4, 5].includes(closeness)) throw badRequest("closeness is 1–5");
  await ownPerson(ctx, personId);
  const userId = ctx.userId;
  const now = ctx.now();
  await ctx.db.sql`
    insert into orbit.tie_labels (user_id, person_id, closeness)
    values (${userId}::uuid, ${personId}::uuid, ${closeness}::smallint)
    on conflict (user_id, person_id) do update set closeness = excluded.closeness`;
  await ctx.db.sql`
    insert into orbit.audit_log (user_id, actor, action, target_table, target_id, details)
    values (${userId}::uuid, 'user', 'score.label', 'people', ${personId}, ${{ closeness }}::jsonb)`;
  const r = await scoreRow(ctx, personId);
  if (r?.features && Object.keys(r.features).length) {
    const score = TIE_LABEL_MIDPOINTS[closeness];
    const line = `You rated this tie ${closeness} of 5`;
    const explanation = [
      line,
      ...(r.explanation ?? []).filter((x) => !x.startsWith("You rated this tie"))
    ].slice(0, 5);
    await ctx.db.sql`
      update orbit.tie_scores set score = ${score}::smallint, band = ${tieBand(score)}, explanation = ${explanation}::text[],
             computed_at = ${now}::timestamptz
       where user_id = ${userId}::uuid and person_id = ${personId}::uuid`;
    await ctx.db.sql`update orbit.people set strength = ${score / 100}::real where id = ${personId}::uuid`;
    return json(200, explainOf(personId, await scoreRow(ctx, personId)));
  }
  const queued2 = await sqlQueue(ctx.db).enqueue({
    kind: "score.person",
    userId,
    payload: { personId, reason: "label" },
    dedupeKey: `score.person:${personId}:label:${now.toISOString().slice(0, 16)}`
  });
  return json(202, { queued: queued2 !== null });
}
var scoreRoutes = {
  "/scores/explain": { method: "POST", auth: true, run: explain },
  "/scores/label": { method: "POST", auth: true, run: label }
};

